        CorrespondenceRow.NotBuilt => Decline(entry, UnresolvedReason.UnsupportedRule),
        CorrespondenceRow.DefinedElsewhere or CorrespondenceRow.BeyondAdapter or CorrespondenceRow.ValueDependencyUnimplemented =>
